const nav=document.querySelector('#nav');Object.keys(modules).forEach((name,i)=>{const b=document.createElement('button');b.innerHTML=`<span class="nav-icon">${navIcons[i]}</span><span class="nav-label">${name}</span>`;b.onclick=()=>openModule(name);nav.append(b)});
let currentModule='Início', currentRows=[], currentPath='', bankAccounts=[], csrfToken='', recoveryCodePath='';
function setTheme(theme){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.body.classList.toggle('dark',dark);localStorage.setItem('lmf-theme',dark?'dark':'light')}
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('#dialog').addEventListener('close',()=>resetPhotoState());
setTheme(localStorage.getItem('lmf-theme')||'light');document.querySelector('#theme-toggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
document.querySelector('#global-search').addEventListener('keydown',async e=>{if(e.key==='Enter'&&e.target.value.trim())await runGlobalSearch(e.target.value.trim())});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#global-search').focus()}});
document.querySelector('#refresh').onclick=()=>openModule(currentModule);
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let toastTimer=null;
function toast(message){const box=document.querySelector('#toast');const text=box.querySelector('span');if(text)text.textContent=message;else box.textContent=message;
// Um <dialog> aberto com showModal() fica na camada superior do navegador e cobre qualquer z-index:
// o aviso precisa ficar DENTRO dele para ser visto (antes, o erro ao salvar ficava escondido e a tela parecia travada).
const open=[...document.querySelectorAll('dialog[open]')].pop();const host=open||document.body;if(box.parentElement!==host)host.append(box);
box.style.display='flex';clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.style.display='none',open?9000:5000)}
function closeOpenDialog(){document.querySelectorAll('dialog[open]').forEach(d=>{if(d.id!=='auth-dialog'&&d.id!=='op-dialog')d.close()})}
// Autorização do administrador (a senha é validada SOMENTE no servidor; aqui ela só trafega uma vez e o campo é limpo).
function requestAuthorization(operation,target,description){return new Promise(resolve=>{const dialog=document.querySelector('#op-dialog'),form=document.querySelector('#op-form'),input=document.querySelector('#op-password'),error=document.querySelector('#op-error'),submit=document.querySelector('#op-submit');let settled=false;
const onClose=()=>finish(null);
const finish=value=>{if(settled)return;settled=true;input.value='';dialog.removeEventListener('close',onClose);if(dialog.open)dialog.close();resolve(value)};
document.querySelector('#op-desc').textContent=description;error.textContent='';input.value='';dialog.addEventListener('close',onClose);document.querySelector('#op-cancel').onclick=()=>finish(null);
form.onsubmit=async e=>{e.preventDefault();const password=input.value;if(!password)return;submit.disabled=true;error.textContent='';try{const r=await api('/api/auth/authorize-operation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,target:String(target),password})});finish(r.token)}catch(err){error.textContent=err.message;input.value='';input.focus()}finally{submit.disabled=false}};
dialog.showModal();input.focus()})}
async function authHeaders(operation,target,description){const token=await requestAuthorization(operation,target,description);return token?{'X-Operation-Authorization':token}:null}
const OUTCOME_LABELS={autorizada:'autorizada',negado:'negada',executada:'executada',falhou:'falhou',bloqueado:'bloqueada'};
function renderAuditPanel(rows){const host=document.querySelector('#content');if(!host||!Array.isArray(rows))return;const panel=document.createElement('div');panel.className='section-panel';panel.innerHTML=`<h2>Auditoria das operações protegidas</h2><p class="field-hint">Registro somente de leitura: quem pediu, o quê, em qual item e o resultado. Senhas e códigos nunca são gravados.</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Operação</th><th>Alvo</th><th>Resultado</th><th>Detalhe</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(String(r.at).replace('T',' '))}</td><td>${esc(r.user)}</td><td>${esc(r.action)}</td><td>${esc(r.target||'')}</td><td>${esc(OUTCOME_LABELS[r.outcome]||r.outcome)}</td><td>${esc(r.details||'')}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum registro ainda.</td></tr>'}</tbody></table></div>`;host.append(panel)}
const MAX_PHOTOS=6,MAX_PHOTO_MB=8;
let photoState={existing:[],pending:[],orderId:null};
const PHONE_HELP='Informe o DDD e o número, só com números. Ex.: (92) 9 9815-8767',CPF_HELP='O CPF tem 11 números. Ex.: 999.888.777-54';
function digitsOnly(v){return String(v??'').replace(/\D/g,'')}
function formatPhone(v){const d=digitsOnly(v).slice(0,11);if(!d)return'';if(d.length<3)return `(${d}`;if(d.length<7)return `(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length<=10)return `(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6)}`;return `(${d.slice(0,2)}) ${d[2]} ${d.slice(3,7)}-${d.slice(7)}`}
function formatCpf(v){const d=digitsOnly(v).slice(0,11);return d.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/^(\d{3})\.(\d{3})\.(\d{3})(\d)/,'$1.$2.$3-$4')}
const SERIAL_MSG='Número de série incorreto. O número de série deve conter exatamente 15 dígitos.';
function cpfDigitsOk(d){if(d.length!==11||/^(\d)\1{10}$/.test(d))return false;for(const size of [9,10]){let t=0;for(let i=0;i<size;i++)t+=Number(d[i])*(size+1-i);if((t*10%11)%10!==Number(d[size]))return false}return true}
function maskProblem(kind,value){const raw=String(value??'').trim();if(kind==='serial')return /^\d{15}$/.test(raw)?'':SERIAL_MSG;if(!raw)return'';if(/[A-Za-zÀ-ÿ]/.test(raw))return 'Use apenas números. '+(kind==='cpf'?CPF_HELP:PHONE_HELP);const n=digitsOnly(raw).length;if(kind==='cpf')return n!==11?CPF_HELP:(cpfDigitsOk(digitsOnly(raw))?'':'CPF inválido: os dígitos verificadores não conferem.');return (n===10||n===11)?'':PHONE_HELP}
document.addEventListener('beforeinput',e=>{const kind=e.target?.dataset?.mask;if(kind&&e.inputType==='insertText'&&e.data&&/\D/.test(e.data))e.preventDefault()});
document.addEventListener('input',e=>{const el=e.target,kind=el?.dataset?.mask;if(!kind)return;const formatted=kind==='serial'?digitsOnly(el.value).slice(0,15):kind==='cpf'?formatCpf(el.value):formatPhone(el.value);if(el.value!==formatted)el.value=formatted;el.setCustomValidity(maskProblem(kind,el.value))});
function renderPhotos(){const grid=document.querySelector('#photo-grid');if(!grid)return;const total=photoState.existing.length+photoState.pending.length;
grid.innerHTML=photoState.existing.map(p=>`<figure><a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="${esc(p.original_name)}" loading="lazy"></a><button type="button" class="photo-remove" aria-label="Excluir foto ${esc(p.original_name)}" onclick="deleteExistingPhoto(${p.id})">×</button></figure>`).join('')+photoState.pending.map((p,i)=>`<figure class="pending"><img src="${esc(p.preview)}" alt="${esc(p.file.name)}"><button type="button" class="photo-remove" aria-label="Remover foto ${esc(p.file.name)}" onclick="removePendingPhoto(${i})">×</button><figcaption>nova</figcaption></figure>`).join('');
const input=document.querySelector('#photo-input');if(input)input.disabled=total>=MAX_PHOTOS;
const hint=document.querySelector('#photo-hint');if(hint)hint.textContent=`${total} de ${MAX_PHOTOS} fotos`+(photoState.pending.length?` · ${photoState.pending.length} será(ão) enviada(s) ao salvar`:'')+(total>=MAX_PHOTOS?' · limite atingido':'')}
// O navegador deduz o tipo pela extensão; aqui conferimos a assinatura real do arquivo (como o servidor faz).
async function sniffImageType(file){const b=new Uint8Array(await file.slice(0,12).arrayBuffer());if(b[0]===0xFF&&b[1]===0xD8&&b[2]===0xFF)return 'image/jpeg';if(b[0]===0x89&&b[1]===0x50&&b[2]===0x4E&&b[3]===0x47&&b[4]===0x0D&&b[5]===0x0A&&b[6]===0x1A&&b[7]===0x0A)return 'image/png';if(b[0]===0x52&&b[1]===0x49&&b[2]===0x46&&b[3]===0x46&&b[8]===0x57&&b[9]===0x45&&b[10]===0x42&&b[11]===0x50)return 'image/webp';return null}
async function addPhotoFiles(fileList){const files=Array.from(fileList),added=[],problems=[];for(const file of files){if(MAX_PHOTOS-photoState.existing.length-photoState.pending.length-added.length<=0){problems.push(`limite de ${MAX_PHOTOS} fotos por OS`);break}if(file.size>MAX_PHOTO_MB*1024*1024){problems.push(`"${file.name}" passa de ${MAX_PHOTO_MB} MB`);continue}if(!await sniffImageType(file)){problems.push(`"${file.name}" não é uma imagem JPEG, PNG ou WebP válida`);continue}added.push({file,preview:URL.createObjectURL(file)})}
photoState.pending.push(...added);renderPhotos();if(problems.length)toast('Algumas fotos não foram adicionadas: '+problems.join('; ')+'.')}
function removePendingPhoto(i){const [gone]=photoState.pending.splice(i,1);if(gone)URL.revokeObjectURL(gone.preview);renderPhotos()}
async function deleteExistingPhoto(id){const p=photoState.existing.find(x=>x.id===id);if(!p||!confirm(`Excluir a foto ${p.original_name}?`))return;try{await api(`/api/service-orders/${photoState.orderId}/photos/${id}`,{method:'DELETE'});photoState.existing=photoState.existing.filter(x=>x.id!==id);renderPhotos();toast('Foto excluída')}catch(e){toast(e.message)}}
function resetPhotoState(){photoState.pending.forEach(p=>URL.revokeObjectURL(p.preview));photoState={existing:[],pending:[],orderId:null}}
function photoSectionMarkup(){return `<fieldset class="photos"><legend>Fotos do equipamento (máx. ${MAX_PHOTOS})</legend><div id="photo-grid" class="photo-grid"></div><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="addPhotoFiles(this.files);this.value=''"><small id="photo-hint" class="field-hint"></small></fieldset>`}
async function responseData(response){const text=await response.text();if(!text)return{};try{return JSON.parse(text)}catch{return{detail:`O servidor respondeu ${response.status}: ${text.slice(0,240)}`}}}
function errorMessage(detail,fallback='Falha na operação'){if(typeof detail==='string'&&detail.trim())return detail;if(Array.isArray(detail)){const messages=detail.map(item=>{if(typeof item==='string')return item;if(item&&typeof item==='object'){if(item.type==='string_pattern_mismatch'&&item.loc?.includes('username'))return 'O login deve começar com letra minúscula e usar apenas letras minúsculas e números.';return String(item.msg||item.message||JSON.stringify(item)).replace(/^Value error,\s*/,'')}return String(item)}).filter(Boolean);return messages.join('; ')||fallback}if(detail&&typeof detail==='object')return detail.message||detail.msg||JSON.stringify(detail);return fallback}
const REQUEST_TIMEOUT_MS=45000;
let moduleAbort=null, moduleLoadToken=0;
function cancelledError(){const e=new Error('Requisição cancelada');e.cancelled=true;return e}
async function api(url,opts={}){const method=(opts.method||'GET').toUpperCase(),headers=new Headers(opts.headers||{});if(csrfToken&&!['GET','HEAD','OPTIONS'].includes(method))headers.set('X-CSRF-Token',csrfToken);const {timeout,signal:outerSignal,...fetchOpts}=opts;const controller=new AbortController();let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort()},timeout??REQUEST_TIMEOUT_MS);if(outerSignal){if(outerSignal.aborted)controller.abort();else outerSignal.addEventListener('abort',()=>controller.abort(),{once:true})}try{let r;try{r=await fetch(url,{...fetchOpts,headers,credentials:'same-origin',signal:controller.signal})}catch(err){if(outerSignal?.aborted)throw cancelledError();if(timedOut)throw Error('O servidor demorou demais para responder. Aguarde alguns segundos e tente novamente.');throw Error('Não foi possível se comunicar com o servidor local. Verifique se o LMF Control continua em execução e tente novamente.')}if(!r.ok){const e=await responseData(r);if(r.status===401&&!url.startsWith('/api/auth/'))showAuthForm(false);throw Error(errorMessage(e.detail,e.message||'Falha na operação'))}if(r.status===204)return null;try{return await r.json()}catch(err){if(outerSignal?.aborted)throw cancelledError();if(timedOut)throw Error('O servidor demorou demais para responder. Aguarde alguns segundos e tente novamente.');throw Error('Resposta inválida do servidor local.')}}finally{clearTimeout(timer)}}
function currency(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v)||0)}
function dateLabel(value,options={day:'2-digit',month:'long',year:'numeric'}){const d=new Date(`${value||new Date().toISOString().slice(0,10)}T12:00:00`);return new Intl.DateTimeFormat('pt-BR',options).format(d)}
function statusClass(text){const s=String(text||'').toLowerCase();return /entregue|conclu|pronto|recebido/.test(s)?'ok':/atras|recus|cancel|negad/.test(s)?'danger':/aguard|penden|diagn/.test(s)?'warn':''}
function card(title,value,icon,module,warn=false){return `<article class="card" onclick="${module?`openModule('${module}')`:''}"><span class="card-icon ${warn?'warn':''}">${icon}</span><div class="card-copy"><span>${esc(title)}</span><strong>${esc(value)}</strong></div></article>`}
function tablePanel(title,rows,columns,module,cls=''){let body=rows.length?`<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td>${c.status?`<span class="status ${statusClass(row[c.key])}">${esc(row[c.key]??'—')}</span>`:esc(row[c.key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Nenhum registro para exibir</div>';return `<section class="panel dashboard-panel ${cls}"><div class="panel-head"><h2>${esc(title)}</h2><button onclick="openModule('${module}')">Ver todas</button></div>${body}</section>`}
function renderDashboard(d){const cards=document.querySelector('#content');const metrics=[
 ['Produtos cadastrados',d.products,'▦','Estoque'],['Estoque baixo',d.low_stock,'⚠','Estoque',true],['Valor do estoque',currency(d.stock_cost),'▣','Estoque'],['OS em andamento',d.service_in_progress,'⚒','Ordens de serviço'],['Aguardando aprovação',d.awaiting_approval,'◷','Ordens de serviço'],
 ['Pedidos pendentes',d.orders_pending,'🛒','Pedidos e encomendas'],['Garantias próximas',d.guarantees_expiring,'⛨','Garantias'],['Fornecedores ativos',d.suppliers,'▣','Fornecedores'],['Receita (mês)',currency(d.income),'▥','Financeiro'],['Despesas (mês)',currency(d.expenses),'▤','Financeiro']];
 cards.innerHTML=`<div class="page-heading"><div><h1>Início</h1><p>Visão geral da sua operação</p></div><div class="date-pill"><strong>${dateLabel(d.as_of,{day:'2-digit',month:'long',year:'numeric'})}</strong><span>${dateLabel(d.as_of,{weekday:'long'})}</span></div></div><div class="cards">${metrics.map(m=>card(...m)).join('')}</div><div class="dashboard-tables">${tablePanel('Ordens de Serviço',d.recent_service_orders||[],[{key:'number',label:'Nº OS'},{key:'customer',label:'Cliente'},{key:'equipment',label:'Equipamento'},{key:'status',label:'Status',status:true},{key:'date',label:'Entrada'}],'Ordens de serviço')}${tablePanel('Produtos em Estoque Baixo',d.low_stock_products||[],[{key:'name',label:'Produto'},{key:'category',label:'Categoria'},{key:'quantity',label:'Estoque atual'}],'Estoque')}${tablePanel('Pedidos Pendentes',d.pending_order_rows||[],[{key:'number',label:'Nº pedido'},{key:'party',label:'Cliente/fornecedor'},{key:'due_on',label:'Previsão'}],'Pedidos e encomendas')}</div>`}
async function openModule(name){closeOpenDialog();if(moduleAbort)moduleAbort.abort();moduleAbort=new AbortController();const signal=moduleAbort.signal,token=++moduleLoadToken,load=url=>api(url,{signal});currentModule=name;document.querySelector('#global-search').value='';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.textContent.trim()===name));const content=document.querySelector('#content');try{if(name==='Início'){currentPath='';const d=await load('/api/dashboard');if(token!==moduleLoadToken)return;renderDashboard(d);return}if(name==='Relatórios'){currentPath='';const r=await load('/api/reports/summary');if(token!==moduleLoadToken)return;content.innerHTML=`<div class="page-heading"><div><h1>Relatórios</h1><p>Indicadores calculados a partir dos registros armazenados</p></div></div><div class="toolbar"><input id="report-search" placeholder="Pesquisar relatórios..." oninput="filterReportSections()"><button type="button" onclick="clearReportSearch()">Limpar</button></div><p id="report-search-empty" class="empty-state" hidden>Nenhum relatório encontrado.</p><div class="cards" id="report-cards">${card('Vendas',r.sales_count,'▤')} ${card('Faturado',currency(r.sales_total),'▣')} ${card('Recebido',currency(r.received),'◉')} ${card('A receber',currency(r.pending),'◷')}</div><div class="section-panel"><h2>Período</h2><label>De <input id="report-start" type="date"></label> <label>Até <input id="report-end" type="date"></label> <label>Status <select id="report-status"><option value="">Todos</option><option value="confirmada">Confirmada</option><option value="pendente">Pendente</option></select></label> <label>ID cliente <input id="report-customer" type="number"></label> <label>ID produto <input id="report-product" type="number"></label> <label>ID fornecedor <input id="report-supplier" type="number"></label> <button onclick="loadReport()">Filtrar</button> <a id="report-export" href="/api/reports/export"><button>Exportar vendas Excel</button></a> <a href="/api/export/products"><button>Exportar estoque Excel</button></a><p>Receitas: ${currency(r.finance.income)} · Despesas: ${currency(r.finance.expenses)} · Valores pendentes: ${currency(r.finance.pending)}</p><p>Margem estimada das vendas: ${currency(r.sales_total-r.estimated_cost)}. Custos estimados usam o custo cadastrado do produto no momento da venda; não incluem taxas, impostos ou despesas indiretas.</p></div><div class="section-panel"><h2>Produtos mais vendidos</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Unidades</th><th>Valor</th></tr></thead><tbody id="report-top">${r.top_products.map(x=>`<tr><td>${esc(x.product)}</td><td>${x.units}</td><td>${currency(x.gross)}</td></tr>`).join('')||'<tr><td colspan="3">Sem vendas registradas</td></tr>'}</tbody></table></div></div><div class="section-panel"><h2>Estoque baixo</h2>${r.low_stock.map(x=>`<p>${esc(x.name)} — ${x.quantity}/${x.minimum}</p>`).join('')||'<p>Nenhum produto abaixo do mínimo.</p>'}</div>`;return}if(name==='Backup e Restauração'){currentPath='';const data=await load('/api/backups');if(token!==moduleLoadToken)return;const items=data.items;const status=data.last_status;content.innerHTML=`<div class="page-heading"><div><h1>Backup e Restauração</h1><p>${esc(status.status)} · ${esc(status.completed_at||'Nenhuma cópia concluída')} ${esc(status.message||'')}</p></div></div><div class="section-panel"><h2>Pastas e banco</h2><p>Dados: ${esc(data.paths.data)}<br>Banco: ${esc(data.paths.database)}<br>Backups: ${esc(data.paths.backups)}<br>Importar: ${esc(data.paths.import)}</p>${data.backup_path_notice?`<p class="warning">${esc(data.backup_path_notice)}</p>`:''}<button onclick="openBackupFolder('backups')">Abrir pasta de backups</button> <button onclick="openBackupFolder('import')">Abrir pasta de importação</button> <button onclick="createBackup()">Criar backup agora</button></div><div class="section-panel"><h2>Agendamento e retenção</h2><form onsubmit="saveBackupSettings(event)"><label>Horário diário <input id="backup-time" type="time" value="${esc(data.settings.backup_time)}"></label> <label>Manter cópias <input id="backup-count" type="number" min="1" value="${data.settings.retention_count}"></label> <label>Por até (dias) <input id="backup-days" type="number" min="1" value="${data.settings.retention_days}"></label> <button>Salvar configurações</button></form><small>O backup automático ocorre enquanto o sistema estiver aberto.</small></div><div class="section-panel"><h2>Backups na pasta de importação</h2><div class="table-wrap"><table><thead><tr><th>Arquivo</th><th>Data</th><th>Integridade</th><th></th></tr></thead><tbody>${data.importable.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.created_at||'—')}</td><td>${esc(b.integrity)} · ${esc(b.status)}</td><td><button onclick="importBackup('${esc(b.name)}')" ${b.integrity==='íntegro'?'':'disabled'}>Importar backup</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhum ZIP encontrado.</td></tr>'}</tbody></table></div></div><div class="section-panel"><h2>Backups locais</h2><div class="table-wrap"><table><thead><tr><th>Arquivo</th><th>Data</th><th>Tamanho</th><th>Integridade e status</th><th>Ações</th></tr></thead><tbody>${items.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.created_at||'—')}</td><td>${(b.size/1024).toFixed(1)} KB</td><td>${esc(b.integrity)} · ${esc(b.status)} ${b.error?`(${esc(b.error)})`:''}</td><td><button onclick="restoreBackup('${esc(b.name)}',${b.complete===false})" ${b.integrity==='íntegro'?'':'disabled'}>Restaurar</button> <button onclick="deleteBackup('${esc(b.name)}',${b.size})">Excluir</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum backup ainda.</td></tr>'}</tbody></table></div></div>`;return}if(name==='Vendas'){currentPath='sales';const rows=await load('/api/sales');if(token!==moduleLoadToken)return;currentRows=rows;content.innerHTML=`<div class="page-heading"><div><h1>Vendas</h1><p>Vendas registradas com baixa transacional de estoque e recebimento</p></div><button onclick="salesForm()">Nova venda</button></div><div class="table-wrap"><table><thead><tr><th>Número</th><th>Data</th><th>Itens</th><th>Status</th><th>Total</th><th>Recebido</th><th>Pendente</th><th>Ação</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.number)}</td><td>${esc(String(s.sold_at).replace('T',' ').slice(0,16))}</td><td>${s.items.map(i=>`${esc(i.quantity)} × ${esc(i.product)}`).join(', ')}</td><td>${esc(s.status)}</td><td>${currency(s.total)}</td><td>${currency(s.received_amount)}</td><td>${currency(Math.max(0,s.total-s.received_amount))}</td><td><button onclick="editSale(${s.id})" ${s.status==='cancelada'?'disabled':''}>Editar</button> <button class="danger-button" onclick="deleteSale(${s.id})">Excluir</button> <button onclick="cancelSale(${s.id})" ${s.status==='cancelada'?'disabled':''}>Cancelar / estornar</button></td></tr>`).join('')||'<tr><td colspan="8">Nenhuma venda registrada.</td></tr>'}</tbody></table></div>`;return}if(name==='Financeiro'){const [entries,accounts,audit]=await Promise.all([load('/api/finance'),load('/api/accounts'),load('/api/audit?limit=30').catch(()=>null)]);if(token!==moduleLoadToken)return;bankAccounts=accounts;currentRows=entries;currentPath='finance';content.innerHTML=`<div class="page-heading"><div><h1>Financeiro</h1><p>Contas locais e lançamentos recebidos ou pagos</p></div></div><div class="account-heading"><h2>Contas financeiras</h2><div><button onclick="removeOpeningBalance()" ${accounts.some(a=>Number(a.opening_balance)!==0)?'':'disabled'}>Remover saldo inicial</button> <button onclick="newRecord('accounts')">Adicionar conta</button></div></div><div class="accounts-grid">${accounts.map(a=>`<article class="account-card"><span class="account-unit">${esc(a.business_unit)}</span><h3>${esc(a.name)}</h3><p>${esc(a.provider)}</p><strong>${currency(a.balance)}</strong><small>Saldo calculado · inicial ${currency(a.opening_balance)} · referência ${esc(a.opening_balance_date||'data não registrada')} · ${a.linked_transaction_count} movimentação(ões)</small><div><button onclick="editAccount(${a.id})">Editar conta</button> <button class="danger-button" onclick="deleteAccount(${a.id})">Excluir conta</button></div></article>`).join('')}</div><div class="toolbar"><input id="search" placeholder="Pesquisar lançamentos..." oninput="filterRows()"><button type="button" onclick="clearModuleSearch()">Limpar</button><button onclick="newRecord('finance')">Novo lançamento</button></div><div id="preview"></div><div id="table"></div>`;renderRows(entries,'finance');renderAuditPanel(audit);return}const path=modules[name],rows=await load(`/api/${path}`);if(token!==moduleLoadToken)return;currentRows=rows;currentPath=path;content.innerHTML=`<div class="page-heading"><div><h1>${esc(name)}</h1><p>Cadastros e histórico operacional</p></div></div><div class="toolbar"><input id="search" placeholder="Pesquisar ${esc(name.toLowerCase())}..." oninput="filterRows()"><button type="button" onclick="clearModuleSearch()">Limpar</button><button onclick="newRecord('${path}')">Novo cadastro</button>${path==='products'?'<button onclick="document.querySelector(\'#xlsx\').click()">Importar Excel</button><input id="xlsx" type="file" accept=".xlsx" hidden onchange="previewExcel(this)">':''}</div><div id="preview"></div><div id="table"></div>`;renderRows(rows,path)}catch(e){if(e.cancelled||token!==moduleLoadToken)return;toast(e.message)}}
function renderRows(rows,path){const keys=fields[path],count=path==='finance'?7:6;document.querySelector('#table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr>${keys.slice(0,count).map(k=>`<th>${esc(labels[k]||k)}</th>`).join('')}<th>Ação</th></tr></thead><tbody>${rows.map(r=>`<tr>${keys.slice(0,count).map(k=>{const v=k==='bank_account_id'?(bankAccounts.find(a=>a.id===r[k])?.name||'—'):r[k];return `<td>${esc(v)}</td>`}).join('')}<td>${path==='products'?`<button onclick="movement(${r.id})">Movimentar</button>`:''}<button onclick="editRecord('${path}',${r.id})">Editar</button><button class="danger-button" onclick="deleteRecord('${path}',${r.id})">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="section-panel empty-state">Nenhum cadastro ainda. Use “Novo cadastro” para começar.</div>'}
function normalizeSearch(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR')}
function filterRows(){const q=normalizeSearch(document.querySelector('#search')?.value||'');const rows=q?currentRows.filter(r=>normalizeSearch(JSON.stringify(r)).includes(q)):currentRows;renderRows(rows,currentPath);if(q&&!rows.length)document.querySelector('#table').innerHTML='<div class="section-panel empty-state">Nenhum resultado encontrado.</div>'}
function clearModuleSearch(){const input=document.querySelector('#search');if(input){input.value='';filterRows();input.focus()}}
function filterReportSections(){const q=normalizeSearch(document.querySelector('#report-search')?.value||'');const blocks=[...document.querySelectorAll('#content .section-panel,#content .cards .card')];let visible=0;for(const block of blocks){const match=!q||normalizeSearch(block.textContent).includes(q);block.hidden=!match;if(match)visible++}document.querySelector('#report-search-empty').hidden=!q||visible>0}
function clearReportSearch(){const input=document.querySelector('#report-search');if(input){input.value='';filterReportSections();input.focus()}}
async function runGlobalSearch(q){try{const modulesToSearch=Object.entries(modules).filter(([,path])=>path);const batches=await Promise.all(modulesToSearch.map(async([module,path])=>{try{const rows=await api(`/api/${path}?q=${encodeURIComponent(q)}`);return rows.filter(row=>JSON.stringify(row).toLowerCase().includes(q.toLowerCase())).map(row=>({module,title:row.name||row.number||row.equipment||row.item||row.description||`Registro ${row.id}`,detail:row.sku||row.status||row.phone||'',id:row.id}))}catch{return []}}));const results=batches.flat();const resultRows=results.length?`<div class="section-panel"><div class="table-wrap"><table><thead><tr><th>Módulo</th><th>Registro</th><th>Detalhe</th><th></th></tr></thead><tbody>${results.map(r=>`<tr><td>${esc(r.module)}</td><td>${esc(r.title)}</td><td>${esc(r.detail)}</td><td><button onclick="openModule('${r.module}')">Abrir módulo</button></td></tr>`).join('')}</tbody></table></div></div>`:'<div class="section-panel empty-state">Nenhum resultado encontrado.</div>';document.querySelector('#content').innerHTML=`<div class="page-heading"><div><h1>Resultados da pesquisa</h1><p>${results.length} registro(s) encontrados para “${esc(q)}”</p></div></div>${resultRows}`;currentModule='Pesquisa';currentPath=''}catch(e){toast(e.message)}}
function fieldMarkup(path,k,obj){const required=['name','description','customer_id','equipment','reported_fault','item','amount'].includes(k);if(['customers','suppliers'].includes(path)&&['phone','whatsapp','document'].includes(k)){const kind=k==='document'?'cpf':'phone',raw=obj[k]??'',problem=maskProblem(kind,raw);const shown=!raw||problem?String(raw):(kind==='cpf'?formatCpf(raw):formatPhone(raw));return `<label>${esc(labels[k]||k)}<input name="${k}" value="${esc(shown)}" type="text" inputmode="numeric" autocomplete="off" data-mask="${kind}" maxlength="${kind==='cpf'?14:16}" placeholder="${kind==='cpf'?'999.888.777-54':'(92) 9 9815-8767'}"><small class="field-hint">${kind==='cpf'?'11 números, sem letras':'DDD + número (até 9 dígitos), sem letras'}</small></label>`}if(path==='finance'&&k==='kind'){const value=obj[k]||'receita';return `<label>Tipo de lançamento<select name="kind"><option value="receita" ${value==='receita'?'selected':''}>Receita</option><option value="despesa" ${value==='despesa'?'selected':''}>Despesa</option></select></label>`}if(path==='finance'&&k==='bank_account_id'){const selected=obj[k]??'';return `<label>${esc(labels[k])}<select name="${k}"><option value="">Sem conta vinculada</option>${bankAccounts.filter(a=>a.active).map(a=>`<option value="${a.id}" ${String(a.id)===String(selected)?'selected':''}>${esc(a.name)} · ${esc(a.provider)}</option>`).join('')}</select></label>`}if(path==='guarantees'&&(k==='ends_on'||k==='duration_days')){const v=obj[k]??'';return `<label>${esc(labels[k]||k)}<input value="${esc(v)}" type="text" disabled placeholder="Calculado automaticamente"><small class="field-hint">${k==='ends_on'?'Vencimento = data de início + 90 dias (definido pelo sistema)':'Fixo em 90 dias a partir da data de início'}</small></label>`}if(k==='active'||k==='received'){return `<label><input type="checkbox" name="${k}" ${obj[k]===false?'':'checked'}> ${k==='active'?'Ativo':'Recebido'}</label>`}const inputType=['opening_balance_date','starts_on','ends_on','entered_on','delivered_on','completed_on','due_on','paid_on'].includes(k)?'date':(['quantity','min_quantity','cost','price','estimate','total','paid','amount','customer_id','supplier_id','service_order_id','bank_account_id','opening_balance','lead_time_days','duration_days'].includes(k)?'number':'text');const value=obj[k]??(k==='business_unit'?'Assistência':k==='provider'?'InfinitePay':k==='entered_on'?new Date().toISOString().slice(0,10):'');return `<label>${esc(labels[k]||k)}<input name="${k}" value="${esc(value)}" type="${inputType}" ${inputType==='number'?'step="any"':''} ${required?'required':''}></label>`}

async function cancelSale(id){if(!confirm('Cancelar esta venda? O estoque será devolvido e os valores recebidos serão registrados como estorno.'))return;const auth=await authHeaders('financeiro.venda.cancelar',id,'Cancelar a venda e estornar os valores recebidos.');if(!auth)return;try{const r=await api(`/api/sales/${id}/cancel`,{method:'POST',headers:auth});toast(r.duplicate_request?'Venda já estava cancelada':'Venda cancelada e estornada');openModule('Vendas')}catch(e){toast(e.message)}}
async function salesForm(){try{const [products,accounts,customers]=await Promise.all([api('/api/products'),api('/api/accounts'),api('/api/customers')]);const available=products.filter(p=>p.active);document.querySelector('#form').innerHTML=`<h2>Registrar venda</h2><form id="saleform"><label>Cliente <select name="customer_id"><option value="">Venda sem identificação</option>${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Produto <select name="product_id" required onchange="saleProductChanged(this)">${available.map(p=>`<option value="${p.id}" data-price="${p.price}" data-stock="${p.quantity}">${esc(p.name)} · estoque ${p.quantity}</option>`).join('')}</select></label><label>Quantidade <input name="quantity" type="number" min="1" value="1" required></label><label>Preço unitário <input name="unit_price" type="number" min="0" step="0.01" required></label><label>Desconto item <input name="discount" type="number" min="0" step="0.01" value="0"></label><label>Desconto total <input name="sale_discount" type="number" min="0" step="0.01" value="0"></label><label>Valor recebido <input name="received_amount" type="number" min="0" step="0.01" value="0"></label><label>Forma de pagamento <input name="payment_method" placeholder="PIX, cartão, dinheiro..."></label><label>Conta de recebimento <select name="bank_account_id"><option value="">Sem conta</option>${accounts.filter(a=>a.active).map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.provider)}</option>`).join('')}</select></label><label>Status<select name="status"><option value="confirmada">Confirmar e baixar estoque</option><option value="pendente">Pendente</option></select></label><button ${available.length?'':'disabled'}>Salvar venda</button></form>`;document.querySelector('#dialog').showModal();const sel=document.querySelector('[name=product_id]');if(sel.options.length)saleProductChanged(sel);document.querySelector('#saleform').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const data={customer_id:f.get('customer_id')?Number(f.get('customer_id')):null,items:[{product_id:Number(f.get('product_id')),quantity:Number(f.get('quantity')),unit_price:Number(f.get('unit_price')),discount:Number(f.get('discount'))}],discount:Number(f.get('sale_discount')),received_amount:Number(f.get('received_amount')),payment_method:f.get('payment_method')||null,bank_account_id:f.get('bank_account_id')?Number(f.get('bank_account_id')):null,status:f.get('status'),request_key:crypto.randomUUID()};try{const out=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':data.request_key},body:JSON.stringify(data)});document.querySelector('#dialog').close();toast(`Venda ${out.number} salva · ${currency(out.total)}`);openModule('Vendas')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
function saleProductChanged(select){const option=select.selectedOptions[0];const price=document.querySelector('[name=unit_price]');if(price&&option)price.value=option.dataset.price||0}
const EQUIPMENT_TYPES=['Celular','Computador','Notebook','Videogame'];
const OS_STATUSES=['Recebido','Em análise','Aguardando aprovação','Em reparo','Pronto','Entregue','Cancelado'];
function serviceOrderFormMarkup(obj){const f=k=>fieldMarkup('service-orders',k,obj);const status=obj.status||'Recebido';
return `<fieldset class="os-section"><legend>1. Identificação</legend><label>Número da OS<input value="${esc(obj.number||'Gerado ao salvar')}" disabled></label>${f('entered_on')}<label>Status<input name="status" list="os-status-list" value="${esc(status)}" required><datalist id="os-status-list">${OS_STATUSES.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></label><label>Tipo de equipamento *<select name="equipment_type" required><option value="">Selecione…</option>${EQUIPMENT_TYPES.map(t=>`<option ${obj.equipment_type===t?'selected':''}>${t}</option>`).join('')}</select></label></fieldset>
<fieldset class="os-section"><legend>2. Dados do cliente</legend><input type="hidden" name="customer_id" id="os-customer-id" value="${esc(obj.customer_id??'')}"><label>CPF *<input id="os-cpf" name="cust_document" data-mask="cpf" inputmode="numeric" maxlength="14" autocomplete="off" placeholder="999.888.777-54" required><small class="field-hint" id="os-cpf-hint">Digite o CPF: se o cliente já existir, os dados são preenchidos.</small></label><label>Identificador do cliente<input id="os-cust-code" disabled placeholder="Gerado ao cadastrar"></label><label>Nome *<input name="cust_name" id="os-cust-name" required></label><label>Telefone<input name="cust_phone" id="os-cust-phone" data-mask="phone" inputmode="numeric" maxlength="16" placeholder="(92) 9 9815-8767"></label></fieldset>
<fieldset class="os-section"><legend>3. Dados do equipamento</legend>${f('equipment')}<label>Número de série *<input name="serial" data-mask="serial" inputmode="numeric" maxlength="15" autocomplete="off" required value="${esc(obj.serial??'')}"><small class="field-hint">Exatamente 15 números (zeros à esquerda são mantidos).</small></label>${f('accessories')}${f('physical_condition')}</fieldset>
<fieldset class="os-section"><legend>4. Defeito e diagnóstico</legend>${f('reported_fault')}${f('diagnosis')}${f('estimate')}${f('notes')}</fieldset>
<fieldset class="os-section"><legend>5. Execução e conclusão</legend>${f('service_executed')}${f('cost')}${f('charged')}${f('approval')}${f('due_on')}${f('delivered_on')}${f('completed_on')}</fieldset>`}
function setupServiceOrderCustomer(obj){const cpf=document.querySelector('#os-cpf'),idEl=document.querySelector('#os-customer-id'),name=document.querySelector('#os-cust-name'),phone=document.querySelector('#os-cust-phone'),code=document.querySelector('#os-cust-code'),hint=document.querySelector('#os-cpf-hint');let seq=0;
const fill=c=>{idEl.value=c?c.id:'';code.value=c?(c.public_code||''):'';if(c){name.value=c.name||'';phone.value=c.phone?formatPhone(c.phone):phone.value;hint.textContent=`Cliente nº ${c.public_code||c.id} encontrado: dados preenchidos.`}else{hint.textContent='Cliente novo: preencha nome e telefone, ele será cadastrado ao salvar a OS.'}};
cpf.addEventListener('input',async()=>{const d=digitsOnly(cpf.value);idEl.value='';code.value='';if(d.length!==11||!cpfDigitsOk(d)){hint.textContent=d.length===11?'CPF inválido: os dígitos verificadores não conferem.':'Digite o CPF: se o cliente já existir, os dados são preenchidos.';return}const mine=++seq;try{const c=await api(`/api/customers/lookup?document=${d}`);if(mine===seq)fill(c)}catch(err){if(mine===seq)fill(null)}});
if(obj.customer_id){api('/api/customers').then(list=>{const c=list.find(x=>x.id===obj.customer_id);if(c){cpf.value=c.document||'';cpf.setCustomValidity(maskProblem('cpf',cpf.value));idEl.value=c.id;name.value=c.name;phone.value=c.phone||'';code.value=c.public_seq!=null?String(c.public_seq).padStart(2,'0'):'';hint.textContent=`Cliente nº ${code.value||c.id}.`}}).catch(()=>{})}}
function newRecord(path,obj={}){resetPhotoState();const form=document.querySelector('#form');form.innerHTML=`<h2>${path==='service-orders'?(obj.id?'Editar ordem de serviço':'Nova ordem de serviço'):`${obj.id?'Editar':'Novo'} ${path==='accounts'?'conta bancária':path==='finance'?'lançamento':'cadastro'}`}</h2><form id="editform">${path==='service-orders'?serviceOrderFormMarkup(obj):fields[path].map(k=>fieldMarkup(path,k,obj)).join('')}${path==='service-orders'?photoSectionMarkup():''}<button id="save-record">Salvar</button></form>`;document.querySelector('#dialog').showModal();if(path==='service-orders')setupServiceOrderCustomer(obj);
document.querySelectorAll('#editform [data-mask]').forEach(el=>el.setCustomValidity(maskProblem(el.dataset.mask,el.value)));
if(path==='service-orders'){photoState.orderId=obj.id||null;renderPhotos();if(obj.id)api(`/api/service-orders/${obj.id}/photos`).then(r=>{if(photoState.orderId===obj.id){photoState.existing=r.items;renderPhotos()}}).catch(err=>toast('Não foi possível carregar as fotos: '+err.message))}
document.querySelector('#editform').onsubmit=async e=>{e.preventDefault();const saveButton=document.querySelector('#save-record');if(saveButton.disabled)return;saveButton.disabled=true;const fd=new FormData(e.target),data=Object.fromEntries(fd);if(['accounts','products','customers','suppliers'].includes(path))data.active=fd.has('active');if(path==='orders')data.received=fd.has('received');if(path==='service-orders'){const customerId=data.customer_id;const cust={name:data.cust_name,document:data.cust_document,phone:data.cust_phone||null};delete data.cust_name;delete data.cust_document;delete data.cust_phone;if(customerId)data.customer_id=Number(customerId);else{delete data.customer_id;data.customer=cust}}for(const k of Object.keys(data)){if(k==='customer'||data[k]===null)continue;if(data[k]==='')data[k]=null;else if(['quantity','min_quantity','cost','price','estimate','total','paid','amount','customer_id','supplier_id','service_order_id','bank_account_id','opening_balance','lead_time_days','duration_days'].includes(k))data[k]=Number(data[k])}if(path==='service-orders'){for(const k of Object.keys(data))if(data[k]===null)delete data[k]}try{let extra={};if(path==='accounts'&&obj.id&&(Number(data.opening_balance||0)!==Number(obj.opening_balance||0)||(data.opening_balance_date||null)!==(obj.opening_balance_date||null))){extra=await authHeaders('financeiro.conta.saldo_inicial.alterar',obj.id,`Alterar o saldo inicial da conta ${obj.name}.`);if(!extra)return}const saved=await api(`/api/${path}${obj.id?'/'+obj.id:''}`,{method:obj.id?'PUT':'POST',headers:{'Content-Type':'application/json',...extra},body:JSON.stringify(data)});let photoError='';
if(path==='service-orders'&&photoState.pending.length){const body=new FormData();photoState.pending.forEach(p=>body.append('files',p.file));try{await api(`/api/service-orders/${saved.id}/photos`,{method:'POST',body,timeout:180000})}catch(err){photoError=err.message}}
document.querySelector('#dialog').close();toast(photoError?`Ordem salva, mas as fotos NÃO foram enviadas: ${photoError} Abra a OS e anexe novamente.`:'Registro salvo');openModule(path==='accounts'?'Financeiro':Object.keys(modules).find(n=>modules[n]===path))}catch(err){toast(err.message)}finally{saveButton.disabled=false}}}
function editRecord(path,id){const row=currentRows.find(x=>x.id===id);newRecord(path,row)}
async function deleteRecord(path,id){const row=currentRows.find(x=>x.id===id);const label=row?.name||row?.number||row?.description||`Registro ${id}`;if(!confirm(`Excluir ${label}?`))return;let auth={};if(path==='finance'){auth=await authHeaders('financeiro.lancamento.excluir',id,`Excluir o lançamento financeiro: ${label}.`);if(!auth)return}try{await api(`/api/${path}/${id}?confirm=true`,{method:'DELETE',headers:auth});toast('Registro excluído');openModule(currentModule)}catch(e){toast(e.message)}}
async function editSale(id){const s=currentRows.find(x=>x.id===id);if(!s)return;const accounts=await api('/api/accounts');bankAccounts=accounts;document.querySelector('#form').innerHTML=`<h2>Editar venda ${esc(s.number)}</h2><form id="sale-edit-form"><label>Cliente (ID)<input name="customer_id" type="number" value="${esc(s.customer_id??'')}"></label><label>Forma de pagamento<input name="payment_method" value="${esc(s.payment_method??'')}"></label><label>Conta<select name="bank_account_id"><option value="">Sem conta</option>${accounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(s.bank_account_id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Observações<textarea name="notes">${esc(s.notes??'')}</textarea></label><p>Itens e valores históricos permanecem registrados.</p><button>Salvar alterações</button></form>`;document.querySelector('#dialog').showModal();document.querySelector('#sale-edit-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const data={customer_id:f.get('customer_id')?Number(f.get('customer_id')):null,payment_method:f.get('payment_method')||null,bank_account_id:f.get('bank_account_id')?Number(f.get('bank_account_id')):null,notes:f.get('notes')||null};try{await api(`/api/sales/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});document.querySelector('#dialog').close();openModule('Vendas')}catch(err){toast(err.message)}}}
async function deleteSale(id){const s=currentRows.find(x=>x.id===id);if(!s||!confirm(`Excluir a venda ${s.number}? Uma venda confirmada repõe o estoque. Movimentações bancárias importadas serão preservadas.`))return;const auth=await authHeaders('financeiro.venda.excluir',id,`Excluir a venda ${s.number} e os lançamentos ligados a ela.`);if(!auth)return;try{await api(`/api/sales/${id}?confirm=true`,{method:'DELETE',headers:auth});toast('Venda excluída');openModule('Vendas')}catch(e){toast(e.message)}}
function editAccount(id){const a=bankAccounts.find(x=>x.id===id);if(a)newRecord('accounts',a)}
async function deleteAccount(id){const a=bankAccounts.find(x=>x.id===id);if(!a||!confirm(`Excluir a conta ${a.name}?`))return;const auth=await authHeaders('financeiro.conta.excluir',id,`Excluir a conta ${a.name}.`);if(!auth)return;try{await api(`/api/accounts/${id}?confirm=true`,{method:'DELETE',headers:auth});openModule('Financeiro')}catch(e){toast(e.message)}}

async function movement(id){const kind=prompt('Digite entrada ou saida:');if(!kind)return;const qty=prompt('Quantidade:');if(!qty)return;const reason=prompt('Motivo:');if(!reason)return;try{await api(`/api/products/${id}/movement?kind=${kind}&quantity=${qty}&reason=${encodeURIComponent(reason)}`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});toast('Estoque atualizado');openModule('Estoque')}catch(e){toast(e.message)}}
async function previewExcel(input){const f=input.files[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const p=await api('/api/import/preview',{method:'POST',body:fd});const suggested=Object.entries(p.suggested_mapping||{}).map(([k,v])=>`${k}=${v}`).join('; ');document.querySelector('#preview').innerHTML=`<div class="section-panel"><b>Aba:</b> ${esc(p.sheet)} · <b>Cabeçalho:</b> linha ${p.header_row}<p><b>Colunas detectadas:</b> ${p.headers.filter(Boolean).map(esc).join(', ')||'nenhuma'}</p><p>Produtos encontrados: ${p.rows}. Valores de vendas/caixa são informativos e não serão lançados como movimentações financeiras.</p><label>Mapeamento sugerido (pode ajustar):<input id="mapping" value="${esc(suggested)}" placeholder="name=Produto; sku=Código"></label><button onclick="doImport()" ${p.rows?'':'disabled'}>Importar produtos</button></div>`;window.importFile=f;window.importSheet=p.sheet;window.importHeaderRow=p.header_row}catch(e){toast(e.message)}}
async function doImport(){const raw=document.querySelector('#mapping').value;const map={};raw.split(';').forEach(x=>{const[a,b]=x.split('=');if(a&&b)map[a.trim()]=b.trim()});const fd=new FormData();fd.append('file',window.importFile);try{const out=await api(`/api/import/products?mapping=${encodeURIComponent(JSON.stringify(map))}&key=sku&sheet_name=${encodeURIComponent(window.importSheet)}&header_row=${window.importHeaderRow}`,{method:'POST',body:fd});toast(`Importados ${out.created}; duplicados ${out.duplicates.length}; erros ${out.errors.length}`);openModule('Estoque')}catch(e){toast(e.message)}}
async function createBackup(){try{const r=await api('/api/backups',{method:'POST'});toast('Backup criado: '+r.file);openModule('Backup e Restauração')}catch(e){toast(e.message)}}
async function restoreBackup(name,incomplete=false){let allowIncomplete=false;if(incomplete){if(!confirm(`ATENÇÃO: ${name} é um backup INCOMPLETO (alguns arquivos ligados aos registros não foram salvos nele). Restaurar mesmo assim?`))return;allowIncomplete=true}if(!confirm(`Restaurar ${name}? O estado atual será copiado antes.`))return;const auth=await authHeaders('backup.restaurar',name,`Restaurar o backup ${name}. Todos os dados atuais serão substituídos (uma cópia de segurança é feita antes).`);if(!auth)return;const query=`confirm=true${allowIncomplete?'&allow_incomplete=true':''}`;try{const r=await api(`/api/backups/${encodeURIComponent(name)}/restore?${query}`,{method:'POST',headers:auth});const d=r.documents||{};toast(`Restaurado. Documentos gravados: ${d.created??0}, já idênticos: ${d.unchanged??0}, substituídos: ${d.replaced??0}. Segurança: ${r.safety_backup}`);openModule('Backup e Restauração')}catch(e){toast(e.message)}}
async function deleteBackup(name,size){if(!confirm(`Excluir ${name} (${(size/1024).toFixed(1)} KB)?`))return;try{await api(`/api/backups/${encodeURIComponent(name)}?confirm=true`,{method:'DELETE'});toast('Backup excluído');openModule('Backup e Restauração')}catch(e){toast(e.message)}}
async function importBackup(name){const b=(await api('/api/backups')).importable.find(x=>x.name===name);if(!b||b.integrity!=='íntegro'){toast('Backup inválido ou incompatível');return}if(!confirm(`Importar ${name}, criado em ${b.created_at}?`))return;try{await api(`/api/backups/import/${encodeURIComponent(name)}`,{method:'POST'});toast('Backup validado e importado. Confirme novamente ao restaurar.');openModule('Backup e Restauração')}catch(e){toast(e.message)}}
async function openBackupFolder(folder){try{await api(`/api/backups/open-folder/${folder}`,{method:'POST'})}catch(e){toast(e.message)}}
async function saveBackupSettings(event){event.preventDefault();try{await api('/api/backups/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({backup_time:document.querySelector('#backup-time').value,retention_count:Number(document.querySelector('#backup-count').value),retention_days:Number(document.querySelector('#backup-days').value)})});toast('Configurações salvas');openModule('Backup e Restauração')}catch(e){toast(e.message)}}
async function loadReport(){try{const q=new URLSearchParams();for(const [key,id] of Object.entries({start:'report-start',end:'report-end',status:'report-status',customer_id:'report-customer',product_id:'report-product',supplier_id:'report-supplier'})){const v=document.querySelector('#'+id).value;if(v)q.set(key,v)}const r=await api('/api/reports/summary?'+q);document.querySelector('#report-cards').innerHTML=`${card('Vendas',r.sales_count,'▤')} ${card('Faturado',currency(r.sales_total),'▣')} ${card('Recebido',currency(r.received),'◉')} ${card('A receber',currency(r.pending),'◷')}`;document.querySelector('#report-top').innerHTML=r.top_products.map(x=>`<tr><td>${esc(x.product)}</td><td>${x.units}</td><td>${currency(x.gross)}</td></tr>`).join('')||'<tr><td colspan="3">Sem vendas registradas</td></tr>';document.querySelector('#report-export').href='/api/reports/export?'+q;toast(`Período: ${r.sales_count} vendas · ${currency(r.sales_total)}`)}catch(e){toast(e.message)}}
async function boot(){try{const status=await fetch('/api/auth/status',{credentials:'same-origin'}).then(r=>r.json());recoveryCodePath=status.recovery_file||'';if(status.authenticated){csrfToken=status.csrf_token;document.querySelector('#signed-in-user').textContent=status.username;document.querySelector('#signed-in-user').hidden=false;document.querySelector('#logout-btn').hidden=false;document.querySelector('#auth-dialog').close();openModule('Início')}else{csrfToken='';showAuthForm(status.setup_required)}}catch(e){toast('Não foi possível verificar a sessão: '+e.message)}}
function showAuthForm(setup){const dialog=document.querySelector('#auth-dialog');const form=document.querySelector('#auth-form');form.innerHTML=`<h2>${setup?'Configurar administrador':'Entrar no LMF Control'}</h2><p>${setup?'Crie a primeira conta administradora. A senha deve ter entre 6 e 12 caracteres.':'Entre com seu usuário e senha para acessar o sistema.'}</p><form id="auth-entry"><label>Usuário<input name="username" minlength="1" maxlength="60" pattern="[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z0-9]+)*" title="Comece com uma letra; use letras, números e pontos entre partes do nome." autocomplete="username" required></label><label>Senha<input name="password" type="password" minlength="6" maxlength="12" autocomplete="${setup?'new-password':'current-password'}" required></label>${setup?'':'<label class="remember-control"><input type="checkbox" name="remember_me"> Lembre de mim</label>'}<button>${setup?'Criar administrador':'Entrar'}</button>${setup?'':'<button type="button" id="forgot-password" class="text-button">Esqueci a senha</button>'}<p id="auth-error" role="alert"></p></form>`;if(!setup)document.querySelector('#forgot-password').onclick=showForgotPassword;if(!dialog.open)dialog.showModal();document.querySelector('#auth-entry').oninput=()=>{document.querySelector('#auth-error').textContent=''};document.querySelector('#auth-entry').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.target));payload.remember_me=!!e.target.elements.remember_me?.checked;try{const response=await fetch(`/api/auth/${setup?'setup':'login'}`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const body=await responseData(response);if(!response.ok)throw Error(errorMessage(body.detail,body.message||'Falha no login'));csrfToken=body.csrf_token;recoveryCodePath=body.recovery_file||recoveryCodePath;if(body.recovery_code)window.alert(`Guarde este código de recuperação em local seguro. Ele permite redefinir a senha: ${body.recovery_code}`);if(body.recovery_file)toast(`Código de recuperação salvo em: ${body.recovery_file}`);document.querySelector('#signed-in-user').textContent=body.username;document.querySelector('#signed-in-user').hidden=false;document.querySelector('#logout-btn').hidden=false;dialog.close();openModule('Início')}catch(err){document.querySelector('#auth-error').textContent=err.message}}}
async function showForgotPassword(){const form=document.querySelector('#auth-form');form.innerHTML=`<h2>Esqueci a senha</h2><p>Informe seu login, o código de recuperação e a nova senha (6 a 12 caracteres).</p><p>Arquivo do código: <code>${esc(recoveryCodePath||'não encontrado')}</code></p><form id="forgot-entry"><label>Login<input name="username" minlength="1" maxlength="60" pattern="[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z0-9]+)*" required></label><label>Código de recuperação<input name="recovery_code" type="text" autocomplete="off" required></label><label>Nova senha<input name="new_password" type="password" minlength="6" maxlength="12" autocomplete="new-password" required></label><button>Redefinir senha</button><button type="button" id="back-to-login">Voltar</button><p id="auth-error" role="alert"></p></form>`;document.querySelector('#back-to-login').onclick=()=>showAuthForm(false);document.querySelector('#forgot-entry').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.target));try{const response=await fetch('/api/auth/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const body=await responseData(response);if(!response.ok)throw Error(errorMessage(body.detail,body.message||'Não foi possível redefinir a senha'));recoveryCodePath=body.recovery_file||recoveryCodePath;toast(body.message||'Senha redefinida.');showAuthForm(false)}catch(err){document.querySelector('#auth-error').textContent=err.message}}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'});csrfToken='';document.querySelector('#signed-in-user').hidden=true;document.querySelector('#logout-btn').hidden=true;showAuthForm(false)}catch(e){toast(e.message)}}
async function removeOpeningBalance(){const accounts=bankAccounts.filter(a=>Number(a.opening_balance)!==0);if(!accounts.length){toast('Não há saldo inicial cadastrado para remover.');return}window.openingBalanceAccounts=accounts;const form=document.querySelector('#form');form.innerHTML=`<h2>Remover saldo inicial</h2><p>Selecione a conta. A data e o valor de referência serão exibidos antes da confirmação.</p><form id="remove-opening-form"><label>Conta<select id="opening-account-select" required>${accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><div id="opening-account-preview" class="section-panel"></div><button>Continuar</button></form>`;const select=document.querySelector('#opening-account-select');const preview=()=>{const a=accounts.find(x=>String(x.id)===select.value);document.querySelector('#opening-account-preview').innerHTML=`<b>${esc(a.name)}</b><p>Saldo inicial: ${currency(a.opening_balance)}</p><p>Data de referência: ${esc(a.opening_balance_date||'não registrada')}</p><p>Movimentações vinculadas: ${a.linked_transaction_count}</p><p>Esta ação zera somente o saldo inicial. Receitas, despesas e transações não serão excluídas.</p>`};select.onchange=preview;preview();document.querySelector('#dialog').showModal();document.querySelector('#remove-opening-form').onsubmit=async e=>{e.preventDefault();const a=accounts.find(x=>String(x.id)===select.value);if(!confirm(`Confirma remover o saldo inicial ${currency(a.opening_balance)} da conta ${a.name}? Referência: ${a.opening_balance_date||'não registrada'}.`))return;let confirmLinked=false;if(a.linked_transaction_count){if(!confirm(`A conta tem ${a.linked_transaction_count} movimentação(ões) financeira(s) ou bancária(s). Confirma novamente que deseja remover apenas o saldo inicial, mantendo todas essas movimentações?`))return;confirmLinked=true}const typed=prompt(`Digite exatamente o nome da conta para confirmar: ${a.name}`);if(typed!==a.name){toast('Confirmação não corresponde. Nenhuma alteração foi feita.');return}const auth=await authHeaders('financeiro.conta.saldo_inicial.remover',a.id,`Remover o saldo inicial da conta ${a.name}.`);if(!auth)return;try{const result=await api(`/api/accounts/${a.id}/remove-opening-balance`,{method:'POST',headers:{'Content-Type':'application/json',...auth},body:JSON.stringify({account_name_confirmation:typed,confirm_linked_transactions:confirmLinked})});document.querySelector('#dialog').close();toast(`Saldo inicial removido. Novo saldo calculado: ${currency(result.balance)}`);openModule('Financeiro')}catch(err){toast(err.message)}}}
boot();
